// Spike for CLIPK-2: observes the general pasteboard the way the capture daemon will and
// reports what macOS allows. Run it from a terminal, then copy text in a few apps.
//
//   swift run pasteboard-probe [seconds]      (default 60)

import AppKit
import ApplicationServices
import Darwin

struct Probe {
    let duration: TimeInterval
    let interval: TimeInterval = 0.25
    let pasteboard = NSPasteboard.general

    static let markerTypes = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
    ]
    static let browsers = [
        "com.apple.Safari": "Safari",
        "com.google.Chrome": "Google Chrome",
        "company.thebrowser.Browser": "Arc",
    ]

    func run() {
        let version = ProcessInfo.processInfo.operatingSystemVersionString
        print("macOS \(version)")
        print("Accessibility trusted: \(AXIsProcessTrusted())")
        print("Pasteboard access behavior: \(accessBehaviorDescription())")
        print(
            "Polling every \(Int(interval * 1000)) ms for \(Int(duration)) s. Copy something now.\n"
        )

        var lastCount = pasteboard.changeCount
        var polls = 0
        var changes = 0
        let started = Date()
        let cpuStart = cpuSeconds()

        while Date().timeIntervalSince(started) < duration {
            polls += 1
            if pasteboard.changeCount != lastCount {
                lastCount = pasteboard.changeCount
                changes += 1
                report(change: changes)
            }
            RunLoop.current.run(until: Date().addingTimeInterval(interval))
        }

        let cpu = cpuSeconds() - cpuStart
        let elapsed = Date().timeIntervalSince(started)
        print("\nPolls: \(polls), changes seen: \(changes)")
        print(
            String(
                format: "CPU time: %.3f s over %.0f s (%.3f %% of one core)", cpu, elapsed,
                cpu / elapsed * 100))
    }

    private func report(change: Int) {
        let app = NSWorkspace.shared.frontmostApplication
        let name = app?.localizedName ?? "?"
        let bundle = app?.bundleIdentifier ?? "?"
        let types = pasteboard.types?.map(\.rawValue) ?? []
        let markers = Self.markerTypes.filter(types.contains).map { $0.split(separator: ".").last! }

        let readStart = Date()
        let text = pasteboard.string(forType: .string)
        let readMs = Date().timeIntervalSince(readStart) * 1000

        print("#\(change) \(name) (\(bundle))")
        print("   types: \(types.prefix(6).joined(separator: ", "))\(types.count > 6 ? ", …" : "")")
        print("   markers: \(markers.isEmpty ? "none" : markers.joined(separator: ", "))")
        print(
            "   text: \(text.map { "\($0.count) chars" } ?? "none"), read took \(String(format: "%.1f", readMs)) ms"
        )
        if let app, AXIsProcessTrusted() {
            print("   window title: \(windowTitle(of: app) ?? "unavailable")")
        }
        if let url = browserURL(for: bundle) {
            print("   browser url: \(url)")
        }
    }

    private func accessBehaviorDescription() -> String {
        if #available(macOS 15.4, *) {
            return String(describing: pasteboard.accessBehavior)
        }
        return "not available (macOS < 15.4)"
    }

    private func windowTitle(of app: NSRunningApplication) -> String? {
        let element = AXUIElementCreateApplication(app.processIdentifier)
        var window: CFTypeRef?
        guard
            AXUIElementCopyAttributeValue(element, kAXFocusedWindowAttribute as CFString, &window)
                == .success, let window
        else { return nil }
        var title: CFTypeRef?
        guard
            AXUIElementCopyAttributeValue(
                window as! AXUIElement, kAXTitleAttribute as CFString, &title) == .success
        else { return nil }
        return title as? String
    }

    private func browserURL(for bundleID: String) -> String? {
        guard let browser = Self.browsers[bundleID] else { return nil }
        let source =
            bundleID == "com.apple.Safari"
            ? "tell application \"\(browser)\" to return URL of front document"
            : "tell application \"\(browser)\" to return URL of active tab of front window"
        var error: NSDictionary?
        let result = NSAppleScript(source: source)?.executeAndReturnError(&error)
        if let error {
            return
                "error \(error["NSAppleScriptErrorNumber"] ?? "?") (\(error["NSAppleScriptErrorMessage"] ?? ""))"
        }
        return result?.stringValue
    }

    private func cpuSeconds() -> Double {
        var usage = rusage()
        getrusage(RUSAGE_SELF, &usage)
        func seconds(_ value: timeval) -> Double {
            Double(value.tv_sec) + Double(value.tv_usec) / 1e6
        }
        return seconds(usage.ru_utime) + seconds(usage.ru_stime)
    }
}

let seconds = CommandLine.arguments.dropFirst().first.flatMap(Double.init) ?? 60
Probe(duration: seconds).run()
